package server.bots;
import client.Character;import client.Job;import java.awt.*;import java.util.List;import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class BotPinkBeanFormationTest {
 @Test void aBuffedDarkKnightApproachesBeforeDispelAndThePartyKeepsOneCastingHeight(){
  var knight=mock(Character.class);var archer=mock(Character.class);var map=mock(server.maps.MapleMap.class);var ariel=mock(server.life.Monster.class);when(map.getMonsterById(8820002)).thenReturn(ariel);when(knight.getMap()).thenReturn(map);when(archer.getMap()).thenReturn(map);when(knight.getJob()).thenReturn(Job.DARKKNIGHT);when(archer.getJob()).thenReturn(Job.BOWMASTER);when(knight.isAlive()).thenReturn(true);when(archer.isAlive()).thenReturn(true);when(archer.getId()).thenReturn(12);when(knight.getPosition()).thenReturn(new Point(-300,-42));when(archer.getPosition()).thenReturn(new Point(-300,-456));when(knight.getPartyMembersOnSameMap()).thenReturn(List.of(knight,archer));when(knight.getSkillLevel(constants.skills.Spearman.HYPER_BODY)).thenReturn(30);when(knight.getBuffedValue(client.BuffStat.HYPERBODYHP)).thenReturn(60);var skill=mock(client.Skill.class);var effect=mock(server.StatEffect.class);when(skill.getEffect(30)).thenReturn(effect);when(effect.calculateBoundingBox(any(Point.class),anyBoolean())).thenAnswer(call->{Point p=call.getArgument(0);return new Rectangle(p.x-300,p.y-200,600,400);});var e=new BotEntry(knight,knight,null);
  try(var pink=mockStatic(BotPinkBeanRun.class);var skills=mockStatic(client.SkillFactory.class);var combat=mockStatic(BotHorntailCombat.class);var walk=mockStatic(BotPinkBeanMovement.class);var manager=mockStatic(BotManager.class)){
   pink.when(()->BotPinkBeanRun.inInstance(knight)).thenReturn(true);skills.when(()->client.SkillFactory.getSkill(constants.skills.Spearman.HYPER_BODY)).thenReturn(skill);manager.when(BotManager::getInstance).thenReturn(mock(BotManager.class));combat.when(()->BotHorntailCombat.safe(knight,archer.getPosition(),map.getAllMonsters())).thenReturn(true);
   assertFalse(BotPinkBeanFormation.allows(knight,new Point(-300,-258)));assertTrue(BotPinkBeanFormation.allows(knight,new Point(-400,-456)));assertTrue(BotPinkBeanFormation.tick(e,knight,true));walk.verify(()->BotPinkBeanMovement.walkTo(e,knight,archer.getPosition(),true));
   when(knight.getPosition()).thenReturn(new Point(-300,-400));e.climbing=true;e.moveTarget=new Point(-300,-456);assertTrue(BotPinkBeanFormation.tick(e,knight,true));walk.verify(()->BotPinkBeanMovement.walkTo(e,knight,new Point(-300,-456),true),times(2));
   when(map.getMonsterById(8820006)).thenReturn(mock(server.life.Monster.class));assertFalse(BotPinkBeanFormation.required(knight));
  }
 }
 @Test void otherRaidsKeepTheirExistingCombatPositions(){var b=mock(Character.class);try(var pink=mockStatic(BotPinkBeanRun.class)){assertTrue(BotPinkBeanFormation.allows(b,new Point(-300,-42)));assertFalse(BotPinkBeanFormation.tick(new BotEntry(b,b,null),b,true));}}

 @Test void returningPinkGearIsScoredAgainstItsHpFloorBeforeGeneralProvisioning(){var b=mock(Character.class);when(b.getClient()).thenReturn(mock(client.BotClient.class));when(b.getJob()).thenReturn(Job.NIGHTLORD);when(b.getMaxHp()).thenReturn(5000);BotPinkBeanReadiness.mark(b);assertEquals(3400,BotPinkBeanEquipment.hpGoal(b));var ordinary=mock(Character.class);when(ordinary.getJob()).thenReturn(Job.NIGHTLORD);assertEquals(0,BotPinkBeanEquipment.hpGoal(ordinary));}

 @Test void bodyFormationTracksTheActualBossRatherThanTheMapsCenter(){var b=mock(Character.class);var map=mock(server.maps.MapleMap.class);var body=mock(server.life.Monster.class);when(b.getMap()).thenReturn(map);when(b.getPosition()).thenReturn(new Point(900,-42));when(map.getMonsterById(8820001)).thenReturn(body);when(body.getPosition()).thenReturn(new Point(-500,-42));assertTrue(BotPinkBeanFormation.side(b,new Point(-300,-42)));assertFalse(BotPinkBeanFormation.side(b,new Point(-600,-42)));when(body.getPosition()).thenReturn(new Point(500,-42));assertFalse(BotPinkBeanFormation.side(b,new Point(300,-42)));assertTrue(BotPinkBeanFormation.side(b,new Point(700,-42)));}
 @Test void aValidOuterFiringPlatformIsNotDiscardedByTheOldCoarseRange(){
  var b=mock(Character.class);var map=mock(server.maps.MapleMap.class);var mob=mock(server.life.Monster.class);when(b.getMap()).thenReturn(map);when(b.getPosition()).thenReturn(new Point(-843,-42));when(b.getJob()).thenReturn(Job.NIGHTLORD);when(mob.getId()).thenReturn(8820002);when(map.getAllMonsters()).thenReturn(List.of());
  var foothold=mock(server.maps.Foothold.class);when(foothold.getX1()).thenReturn(-550);when(foothold.getX2()).thenReturn(-430);when(foothold.getY1()).thenReturn(-277);when(foothold.getY2()).thenReturn(-277);var region=new BotNavigationGraph.Region(0,List.of(new BotNavigationGraph.Segment(foothold)));var graph=spy(new BotNavigationGraph(270050100,1,List.of(region),java.util.Map.of(0,region),java.util.Map.of(),java.util.Map.of(),java.util.Set.of()));doReturn(0).when(graph).findRegionId(any(),any());doReturn(true).when(graph).canReach(anyInt(),anyInt(),anyInt());var e=new BotEntry(b,b,null);var boxes=mock(server.bots.combat.BotMobHitboxProvider.class);when(boxes.getMobBounds(mob)).thenReturn(new Rectangle(-56,-457,123,143));
  try(var pink=mockStatic(BotPinkBeanRun.class);var weapon=mockStatic(BotAttackExecutionProvider.class);var graphs=mockStatic(BotNavigationGraphProvider.class);var travel=mockStatic(BotNavigationManager.class);var damage=mockStatic(BotZakumCombat.class);var hit=mockStatic(server.bots.combat.BotMobHitboxProvider.class);var formation=mockStatic(BotPinkBeanFormation.class);var stance=mockStatic(BotPinkBeanStances.class);var heal=mockStatic(BotHorntailHealingAnchor.class);var firing=mockStatic(BotHorntailFiringPosition.class);var combat=mockStatic(BotCombatManager.class)){
   pink.when(()->BotPinkBeanRun.inInstance(b)).thenReturn(true);weapon.when(()->BotAttackExecutionProvider.getEquippedWeaponType(b)).thenReturn(client.inventory.WeaponType.CLAW);graphs.when(()->BotNavigationGraphProvider.peekGraph(map,e.movementProfile)).thenReturn(graph);damage.when(()->BotZakumCombat.canDamage(b,mob)).thenReturn(true);hit.when(server.bots.combat.BotMobHitboxProvider::getInstance).thenReturn(boxes);formation.when(()->BotPinkBeanFormation.allows(eq(b),any())).thenReturn(true);stance.when(()->BotPinkBeanStances.allows(eq(b),any(),eq(mob))).thenReturn(true);heal.when(()->BotHorntailHealingAnchor.covers(eq(b),any())).thenReturn(true);firing.when(()->BotHorntailFiringPosition.allows(eq(b),any(),eq(mob))).thenReturn(true);combat.when(()->BotCombatManager.clientProjectileHitBox(b,false,1f)).thenReturn(new Rectangle(-838,-92,595,100));
   assertNotNull(BotHorntailCombat.stance(e,b,List.of(mob)));pink.when(()->BotPinkBeanRun.inInstance(b)).thenReturn(false);assertNull(BotHorntailCombat.stance(e,b,List.of(mob)));
  }
 }
 @Test void bodyFormationLetsTheKnightReachMeleeWhileRangedKeepsNativeBuffDistance(){
  var b=mock(Character.class);var bow=mock(Character.class);var map=mock(server.maps.MapleMap.class);var body=mock(server.life.Monster.class);var skill=mock(client.Skill.class);var fx=mock(server.StatEffect.class);
  when(b.getMap()).thenReturn(map);when(map.getMonsterById(8820001)).thenReturn(body);when(body.getPosition()).thenReturn(new Point(0,-42));when(b.getPosition()).thenReturn(new Point(500,-42));when(b.getJob()).thenReturn(Job.DARKKNIGHT);when(b.isAlive()).thenReturn(true);when(bow.isAlive()).thenReturn(true);when(bow.getJob()).thenReturn(Job.BOWMASTER);when(bow.getMap()).thenReturn(map);when(bow.getPosition()).thenReturn(new Point(500,-42));when(bow.getPartyMembersOnSameMap()).thenReturn(List.of(b,bow));when(b.getPartyMembersOnSameMap()).thenReturn(List.of(b,bow));when(b.getSkillLevel(constants.skills.Spearman.HYPER_BODY)).thenReturn(30);when(skill.getEffect(30)).thenReturn(fx);
  when(fx.calculateBoundingBox(any(Point.class),eq(false))).thenAnswer(c->{Point p=c.getArgument(0);return new Rectangle(p.x-300,p.y-200,600,400);});
  try(var pink=mockStatic(BotPinkBeanRun.class);var skills=mockStatic(client.SkillFactory.class)){
   pink.when(()->BotPinkBeanRun.inInstance(any())).thenReturn(true);skills.when(()->client.SkillFactory.getSkill(constants.skills.Spearman.HYPER_BODY)).thenReturn(skill);
   assertTrue(BotPinkBeanFormation.allows(b,new Point(150,-42)));assertFalse(BotPinkBeanFormation.allows(bow,new Point(500,-42)));assertTrue(BotPinkBeanFormation.allows(bow,new Point(250,-42)));
  }
 }
}
